python3 -c "import openpyxl; from openpyxl.utils import get_column_letter; 
wb = openpyxl.load_workbook('protein_expression.xlsx'); 
task = wb['Task']; 
for r in range(11, 21): 
    for c in range(3, 13): 
        protein_id_cell = f'$A{r}'; 
        sample_name_cell = f'{get_column_letter(c)}$10'; 
        formula = f'=INDEX(Data!$D$2:$BC$201, MATCH({protein_id_cell}, Data!$A$2:$A$201, 0), MATCH({sample_name_cell}, Data!$D$1:$BC$1, 0))'; 
        task.cell(row=r, column=c).value = formula; 
for c in range(2, 12): 
    protein_row = c + 9; 
    task.cell(row=24, column=c).value = f'=AVERAGE($C{protein_row}:$G{protein_row})'; 
    task.cell(row=25, column=c).value = f'=STDEV.S($C{protein_row}:$G{protein_row})'; 
    task.cell(row=26, column=c).value = f'=AVERAGE($H{protein_row}:$L{protein_row})'; 
    task.cell(row=27, column=c).value = f'=STDEV.S($H{protein_row}:$L{protein_row})'; 
for r in range(32, 42): 
    protein_index = r - 31; 
    stats_col = get_column_letter(protein_index + 1); 
    task.cell(row=r, column=4).value = f'={stats_col}$26 - {stats_col}$24'; 
    task.cell(row=r, column=3).value = f'=2^{get_column_letter(4)}{r}'; 
    task.cell(row=r, column=1).value = f'=$A{r-21}'; 
    task.cell(row=r, column=2).value = f'=$B{r-21}'; 
wb.save('protein_expression.xlsx')"

